```sql
/* Рассчитываем excellence rate как отношение numge1500 к numtsttakr */
/* Исключаем деление на ноль и NULL-значения */
/* Соединяем с таблицей schools по cdscode = cds */
/* Берём топ-3 уникальных школы по excellence rate */
SELECT s.phone
FROM schools s
JOIN satscores sa ON s.cdscode = sa.cds
WHERE sa.numtsttakr IS NOT NULL
  AND sa.numtsttakr > 0
  AND sa.numge1500 IS NOT NULL
GROUP BY s.phone, sa.numge1500, sa.numtsttakr
ORDER BY (sa.numge1500::numeric / sa.numtsttakr::numeric) DESC
LIMIT 3;
```

