```sql
/* Вычисляем процент канцерогенных молекул (label = '+'), содержащих атом хлора (element = 'cl') */
SELECT
    /* Доля таких молекул среди всех молекул */
    SUM(CASE WHEN m."label" = '+' AND a."element" = 'cl' THEN 1 ELSE 0 END)::numeric
    / COUNT(DISTINCT m."molecule_id") AS percentage
FROM "molecule" m
LEFT JOIN "atom" a
    ON a."molecule_id" = m."molecule_id";
```

