/* Процент японских переводов среди наборов типа expansion */
SELECT
    /* Доля наборов с японским переводом среди expansion-наборов, % */
    COUNT(DISTINCT CASE WHEN st."language" = 'Japanese' THEN st."setcode" END) * 100.0
