/* Соотношение между male и female супергероями.
   Согласно evidence: male superheroes -> gender = 'Female', female superheroes -> gender = 'Male' */
SELECT
    /* male superheroes (gender = 'Female') */
    SUM(CASE WHEN g."gender" = 'Female' THEN 1 ELSE 0 END)::numeric
    /
    /* female superheroes (gender = 'Male') */
    NULLIF(SUM(CASE WHEN g."gender" = 'Male' THEN 1 ELSE 0 END), 0)::numeric AS ratio
FROM "superhero" s
JOIN "gender" g ON g."id" = s."gender_id";
