```sql
/* Разница в потреблении газа между клиентами, платящими в CZK и EUR, за 2012 год */
SELECT
  /* Потребление клиентов с валютой CZK за 2012 */
  SUM(CASE WHEN c."currency" = 'CZK' THEN ym."consumption" ELSE 0 END)
  -
  /* Потребление клиентов с валютой EUR за 2012 */
  SUM(CASE WHEN c."currency" = 'EUR' THEN ym."consumption" ELSE 0 END) AS "difference"
FROM "yearmonth" ym
JOIN "customers" c ON c."customerid" = ym."customerid"
WHERE SUBSTRING(ym."date", 1, 4) = '2012'
  AND c."currency" IN ('CZK', 'EUR');
```
